// Helpers for Nepal integrations (Khalti, eSewa, connectIPS, IRD CBMS).

// ── Bikram Sambat (BS) dates ──
// Month lengths for BS 2070-2099, one digit per month = days - 29 (from the
// maintained open-source calendars py-nepali / Nepali-Date-Picker, which agree).
// BS 2070-01-01 = 2013-04-14 AD. Extend the table when IRD publishes later years.
const BS_START = 2070;
const BS_REF_UTC = Date.UTC(2013, 3, 14);
const BS_DATA = '222322011011,223222101011,232321101011,232321110012,222322101011,223222101011,232321110011,232321110102,222322101011,223222101011,232321110011,232321110102,223222101011,223222101011,232321110012,132321110102,223222101011,223321101011,232321110012,132321110102,223222101011,223321101011,232321110012,222322011002,223222101011,223321101011,232321110012,222322011011,223222101011,223321101011'.split(',').map((y) => [...y].map((d) => Number(d) + 29));

/** AD date (Date, or a 'YYYY-MM-DD[ HH:MM:SS]' UTC string) -> { y, m, d } in BS, by the Nepal calendar day. */
export function toBS(input = new Date()) {
  const date = input instanceof Date ? input : new Date(String(input).replace(' ', 'T') + (/[zZ]|[+-]\d\d:?\d\d$/.test(String(input)) ? '' : 'Z'));
  const nepal = new Date(date.getTime() + 345 * 60000); // Nepal is UTC+5:45
  let days = Math.floor((Date.UTC(nepal.getUTCFullYear(), nepal.getUTCMonth(), nepal.getUTCDate()) - BS_REF_UTC) / 86400000);
  if (days < 0) throw new Error('Date is before BS 2070.');
  for (let yi = 0; yi < BS_DATA.length; yi++) {
    for (let mi = 0; mi < 12; mi++) {
      const len = BS_DATA[yi][mi];
      if (days < len) return { y: BS_START + yi, m: mi + 1, d: days + 1 };
      days -= len;
    }
  }
  throw new Error('Date is after BS 2099 -- update the calendar table in _nepal.js.');
}
const p2 = (n) => String(n).padStart(2, '0');
/** "2083.06.14" (IRD format YYYY.MM.DD). */
export const bsString = (bs) => `${bs.y}.${p2(bs.m)}.${p2(bs.d)}`;
/** Nepal's fiscal year starts on Shrawan 1 (month 4): "2083.084" (IRD format YYYY.0YY). */
export const fiscalYear = (bs) => { const start = bs.m >= 4 ? bs.y : bs.y - 1; return `${start}.${String(start + 1).slice(1)}`; };

// ── Payments ──
export const paisa = (amount) => { const n = Math.round(Number(amount) * 100); if (!Number.isFinite(n) || n <= 0) throw new Error('This sale has no amount to charge.'); return n; };
export const rupees = (p) => (p / 100).toFixed(2);
export const randomToken = (bytes = 18) => [...crypto.getRandomValues(new Uint8Array(bytes))].map((b) => b.toString(16).padStart(2, '0')).join('');
export const requireNpr = (tx, name) => { if (String(tx.currency || 'NPR').toUpperCase() !== 'NPR') throw new Error(`${name} only takes payments in NPR.`); };

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function html(title, body, status = 200) {
  return new Response(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title>
<style>body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:#fdecec;color:#201414;display:grid;place-items:center;min-height:100vh}
main{background:#fff;border:1px solid #e6caca;border-radius:16px;padding:28px 24px;max-width:420px;margin:16px;text-align:center}
h1{font-size:1.3rem;margin:0 0 8px}p{color:#574646;line-height:1.5}.amt{font-size:1.8rem;font-weight:700;color:#201414;margin:8px 0}
button{background:#c81e2c;color:#fff;border:0;border-radius:999px;padding:14px 26px;font-weight:700;font-size:1rem;cursor:pointer}
.ok{color:#1e7a3e;font-weight:700}.err{color:#b3261e;font-weight:700}</style></head><body><main>${body}</main></body></html>`,
  { status, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer', 'X-Frame-Options': 'DENY' } });
}

/** A page that posts a form to a payment gateway (auto-submits; button as a fallback). */
export function gatewayFormPage({ title, amountText, action, fields, buttonLabel }) {
  const inputs = Object.entries(fields).map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join('');
  return html(title, `<h1>${esc(title)}</h1><div class="amt">${esc(amountText)}</div>
<form id="f" method="POST" action="${esc(action)}">${inputs}<button type="submit">${esc(buttonLabel)}</button></form>
<p>Taking you to the payment page&hellip;</p><script>setTimeout(function(){document.getElementById('f').submit()},300)</script>`);
}

/** A page with one button to an app link (e.g. viber://...). */
export function linkPage(title, text, href, label) {
  return html(title, `<h1>${esc(title)}</h1><p>${esc(text)}</p><p><a href="${esc(href)}" style="display:inline-block;background:#c81e2c;color:#fff;border-radius:999px;padding:14px 26px;font-weight:700;text-decoration:none">${esc(label)}</a></p>`);
}

export function resultPage(ok, text) {
  return html(ok ? 'Payment received' : 'Payment not completed', ok
    ? `<h1 class="ok">Payment received</h1><p>${esc(text || 'Thank you! The shop can see your payment.')}</p>`
    : `<h1 class="err">Payment not completed</h1><p>${esc(text || 'Nothing was charged. Please show this screen to the shop or try again.')}</p>`, ok ? 200 : 400);
}

/** Tells Stratek a sale was paid (it marks it "Paid online"; a person still presses Settle). */
export async function emitPaid(emit, { integration, provider, txId, amountPaisa, ref, livemode, method }) {
  await emit({ id: `${integration}-${ref}`, type: 'payment.succeeded', data: { transactionId: String(txId), amount: amountPaisa / 100, currency: 'NPR', provider, integration, providerRef: String(ref), method: method || integration, livemode } });
}

modules.integrations/_oauth.js:
// OAuth 2.0 for integrations that need the owner to log in and allow access
// (QuickBooks, Xero, Zoho Books). The owner creates their OWN app with the
// provider (bring your own app), pastes its client ID / secret in Set up, and
// registers this redirect URI with the provider:
//     <connector>/oauth/<integration>/callback
// Then "Connect <name>" (Integrations tab, signed-in person only) opens
//     <connector>/oauth/<integration>/start/<mode>/<state>  -> provider login
// and the provider sends the owner back to /callback, where the code is swapped
// for tokens that stay in this connector (integration memory, per mode).
//
// An integration declares:
//   oauth: {
//     authorizeUrl(env, mode), tokenUrl(env, mode), scope(env),
//     clientId(env), clientSecret(env),
//     tokenAuth: 'basic' | 'body',              // how the client secret is sent
//     extraAuthParams?: { access_type: 'offline', ... },
//     afterConnect?({ tokens, query, env, mode, store }) -> extra fields to keep (e.g. realmId, tenantId)
//   }

const STATE_TTL = 15 * 60 * 1000;
const rnd = () => [...crypto.getRandomValues(new Uint8Array(24))].map((b) => b.toString(16).padStart(2, '0')).join('');

/** Used by the integration's "connect" action: a one-time link for the signed-in owner. */
export async function oauthStartLink({ db, integration, mode, origin }) {
  const state = rnd();
  await db.put(`oauth_state:${state}`, { id: integration.id, mode, exp: Date.now() + STATE_TTL });
  return `${origin}/oauth/${integration.id}/start/${mode}/${state}`;
}

export const redirectUri = (origin, id) => `${origin}/oauth/${id}/callback`;

/** GET /oauth/:int/start/:mode/:state -> 302 to the provider. */
export async function oauthStart({ db, integration, mode, state, env, origin }) {
  const s = await db.get(`oauth_state:${state}`);
  if (!s || s.id !== integration.id || s.mode !== mode || s.exp < Date.now()) throw new Error('This connect link has expired. Press "Connect" in Stratek again.');
  const o = integration.oauth;
  const u = new URL(o.authorizeUrl(env, mode));
  u.searchParams.set('response_type', 'code');
  u.searchParams.set('client_id', o.clientId(env));
  u.searchParams.set('redirect_uri', redirectUri(origin, integration.id));
  u.searchParams.set('scope', o.scope(env));
  u.searchParams.set('state', state);
  for (const [k, v] of Object.entries(o.extraAuthParams || {})) u.searchParams.set(k, v);
  return Response.redirect(u.toString(), 302);
}

async function tokenRequest(integration, env, mode, params, origin) {
  const o = integration.oauth;
  const body = new URLSearchParams(params);
  const headers = { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' };
  if (o.tokenAuth === 'basic') headers.Authorization = `Basic ${btoa(`${o.clientId(env)}:${o.clientSecret(env)}`)}`;
  else { body.set('client_id', o.clientId(env)); body.set('client_secret', o.clientSecret(env)); }
  if (params.grant_type === 'authorization_code') body.set('redirect_uri', redirectUri(origin, integration.id));
  const res = await fetch(o.tokenUrl(env, mode), { method: 'POST', headers, body });
  const j = await res.json().catch(() => null);
  if (!res.ok || !j?.access_token) throw new Error(`${integration.name} did not give a token (${j?.error_description || j?.error || res.status}). Check the client ID / secret and the redirect URI.`);
  return j;
}

/** GET /oauth/:int/callback?code&state -> tokens stored; returns { mode }. */
export async function oauthCallback({ db, integration, url, envFor, storeFor, origin }) {
  const state = url.searchParams.get('state') || '';
  const s = await db.get(`oauth_state:${state}`);
  if (!s || s.id !== integration.id || s.exp < Date.now()) throw new Error('This connect link has expired. Press "Connect" in Stratek again.');
  await db.delete(`oauth_state:${state}`);
  if (url.searchParams.get('error')) throw new Error(`${integration.name}: ${url.searchParams.get('error_description') || url.searchParams.get('error')}`);
  const code = url.searchParams.get('code');
  if (!code) throw new Error(`${integration.name} did not send a code back.`);
  const env = await envFor(s.mode);
  const store = storeFor(s.mode);
  const t = await tokenRequest(integration, env, s.mode, { grant_type: 'authorization_code', code }, origin);
  const query = Object.fromEntries(url.searchParams);
  const saved = { access_token: t.access_token, refresh_token: t.refresh_token || null, expires_at: Date.now() + (Number(t.expires_in) || 3600) * 1000, connectedAt: new Date().toISOString() };
  const extra = integration.oauth.afterConnect ? await integration.oauth.afterConnect({ tokens: saved, query, env, mode: s.mode, store }) : {};
  await store.put('oauth', { ...saved, ...(extra || {}) });
  return { mode: s.mode, extra };
}

/** A fresh access token (refreshes when needed). Throws if not connected. */
export async function accessToken(integration, env, store, mode, origin = '') {
  const t = await store.get('oauth');
  if (!t?.access_token) throw new Error(`${integration.name} is not connected yet. Press "Connect ${integration.name}" on the Integrations tab.`);
  if (t.expires_at > Date.now() + 60000) return t;
  if (!t.refresh_token) throw new Error(`${integration.name} needs connecting again (the access expired).`);
  let n;
  try { n = await tokenRequest(integration, env, mode, { grant_type: 'refresh_token', refresh_token: t.refresh_token }, origin); }
  catch { throw new Error(`${integration.name} needs connecting again (the saved login was refused). Press "Connect ${integration.name}".`); }
  const next = { ...t, access_token: n.access_token, refresh_token: n.refresh_token || t.refresh_token, expires_at: Date.now() + (Number(n.expires_in) || 3600) * 1000 };
  await store.put('oauth', next);
  return next;
}

export async function oauthStatus(store) {
  const t = await store.get('oauth');
  return t?.access_token ? { connected: true, since: t.connectedAt } : { connected: false };
}

