modules.integrations/cloudbeds.js:
// cloudbeds -- charge a restaurant, bar, spa or shop sale to a hotel guest's room in
// Cloudbeds, and see who is in house / arriving today.
// Cloudbeds -> Account -> Apps & Marketplace -> API credentials -> create a property API
// key (self-service API access). Scopes: read:hotel, read:reservation, write:item.
//   API: https://api.cloudbeds.com/api/v1.2 (header x-api-key)
//        GET /getHotelDetails, GET /getReservations (status=checked_in / checkInFrom),
//        POST /postCustomItem (form data; referenceID stops a double charge)
// Buttons: Test Cloudbeds, Guests in house, Today's arrivals (Integrations tab);
// Charge to room (sale details -- needs a person, it bills a guest).
// Nothing is settled automatically: the guest pays the hotel at check-out, and a person
// settles the Stratek sale.

import { sale } from './_util.js';
import { readJson } from './_ship.js';

const BASE = 'https://api.cloudbeds.com/api/v1.2';
const pid = (env) => String(env.CLOUDBEDS_PROPERTY_ID || '').trim();

async function cb(env, method, path, params) {
  const q = method === 'GET' ? `?${new URLSearchParams({ propertyID: pid(env), ...params })}` : '';
  const res = await fetch(`${BASE}${path}${q}`, { method, headers: { 'x-api-key': String(env.CLOUDBEDS_API_KEY).trim(), Accept: 'application/json', ...(method === 'POST' ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}) }, body: method === 'POST' ? new URLSearchParams(params) : undefined });
  const j = await readJson(res);
  if (res.status === 401 || res.status === 403) throw new Error('Cloudbeds did not accept the API key (it needs read:hotel, read:reservation and write:item).');
  if (!res.ok || j?.success === false) throw new Error(`Cloudbeds: ${j?.message || `error ${res.status}`}`);
  return j;
}

/** In-house reservations with their room names. */
async function inHouse(env) {
  const j = await cb(env, 'GET', '/getReservations', { status: 'checked_in', includeGuestsDetails: 'true', pageSize: '100' });
  return (j.data || []).map((r) => {
    const rooms = new Set();
    for (const g of Object.values(r.guestList || {})) for (const rm of [].concat(g.rooms || [])) if (rm?.roomName) rooms.add(String(rm.roomName));
    for (const rm of [].concat(r.rooms || [])) if (rm?.roomName) rooms.add(String(rm.roomName));
    return { id: String(r.reservationID), guest: String(r.guestName || ''), rooms: [...rooms] };
  });
}

export function matchGuest(list, q) {
  const s = String(q || '').trim().toLowerCase();
  if (!s) throw new Error('Enter the room number or the guest name.');
  const byRoom = list.filter((r) => r.rooms.some((n) => n.toLowerCase() === s || n.toLowerCase().replace(/^room\s*/, '') === s));
  const hits = byRoom.length ? byRoom : list.filter((r) => r.guest.toLowerCase().includes(s));
  if (!hits.length) throw new Error(`No checked-in guest matches "${q}".`);
  if (hits.length > 1) throw new Error(`"${q}" matches ${hits.length} guests (${hits.slice(0, 4).map((h) => `${h.guest} ${h.rooms.join('/')}`).join(', ')}). Use the room number.`);
  return hits[0];
}

/** Sale lines for the folio, plus one line for tax / service / rounding so the total matches the bill. */
export function folioLines(tx) {
  const items = (tx.items || []).map((i) => ({ name: String(i.name).slice(0, 100), price: Number(i.price), qty: Number(i.qty || 1) }));
  const sum = Math.round(items.reduce((s, i) => s + i.price * i.qty, 0) * 100) / 100;
  const diff = Math.round((Number(tx.amount) - sum) * 100) / 100;
  if (!items.length || diff < 0) return [{ name: `Sale #${tx.id}`, price: Number(tx.amount), qty: 1 }];
  return diff > 0 ? [...items, { name: 'VAT, service & rounding', price: diff, qty: 1 }] : items;
}

export default {
  id: 'cloudbeds',
  name: 'Cloudbeds',
  category: 'hospitality',
  status: 'available',
  color: '#1C4BDB',
  description: "Hotel PMS: charge a restaurant, bar or shop sale to a guest's room, and see who is in house.",
  docsUrl: 'https://developers.cloudbeds.com/',
  test: { support: 'none', note: 'Cloudbeds has no test mode; ask Cloudbeds for a demo property to try it.' },
  secrets: [
    { name: 'CLOUDBEDS_API_KEY', label: 'Cloudbeds API key', hint: 'Cloudbeds -> Apps & Marketplace -> API credentials -> new key (read:hotel, read:reservation, write:item).' },
    { name: 'CLOUDBEDS_PROPERTY_ID', label: 'Property ID', hint: 'Shown next to the API key; "Test Cloudbeds" confirms it.' },
  ],
  actions: [
    {
      id: 'test', label: 'Test Cloudbeds', placement: ['settings'], fields: [],
      async run({ env }) {
        const h = (await cb(env, 'GET', '/getHotelDetails', {})).data || {};
        return { type: 'message', title: 'Cloudbeds is connected', text: `${h.propertyName || 'Property'} (${h.propertyCurrency?.currencyCode || h.propertyCurrency || '?'}).` };
      },
    },
    {
      id: 'in_house', label: 'Guests in house', placement: ['settings'], fields: [],
      async run({ env }) {
        const list = await inHouse(env);
        return { type: 'message', title: `${list.length} guest${list.length === 1 ? '' : 's'} in house`, text: list.length ? list.slice(0, 30).map((r) => `${r.rooms.join('/') || '?'} ${r.guest}`).join(' · ') : 'Nobody is checked in.' };
      },
    },
    {
      id: 'arrivals', label: "Today's arrivals", placement: ['settings'], fields: [],
      async run({ env }) {
        const today = new Date(Date.now() + 345 * 60000).toISOString().slice(0, 10);
        const j = await cb(env, 'GET', '/getReservations', { checkInFrom: today, checkInTo: today, status: 'confirmed', pageSize: '100' });
        const list = j.data || [];
        return { type: 'message', title: `${list.length} arrival${list.length === 1 ? '' : 's'} today`, text: list.length ? list.slice(0, 30).map((r) => r.guestName).join(' · ') : 'No arrivals today.' };
      },
    },
    {
      id: 'post_to_room', outbound: true, label: 'Charge to room (Cloudbeds)', placement: ['transaction'],
      fields: [{ name: 'roomOrGuest', label: 'Room number or guest name', type: 'text', required: true }],
      async run({ env, fields, context, store, mode }) {
        if (mode === 'test') throw new Error('Cloudbeds has no test mode -- switch the shop to Live to charge a room.');
        const tx = sale(context);
        const had = await store.get(`tx:${tx.id}`);
        if (had) return { type: 'status', title: 'Cloudbeds', status: 'Already charged', text: `Sale #${tx.id} is on ${had.guest}'s bill (room ${had.room}).` };
        const g = matchGuest(await inHouse(env), fields.roomOrGuest);
        const lines = folioLines(tx);
        const form = { propertyID: pid(env), reservationID: g.id, referenceID: `stratek-${tx.id}`, itemPaid: 'false' };
        lines.forEach((l, n) => Object.assign(form, { [`items[${n}][appItemID]`]: `stratek-${tx.id}-${n + 1}`, [`items[${n}][itemName]`]: l.name, [`items[${n}][itemPrice]`]: String(l.price), [`items[${n}][itemQuantity]`]: String(l.qty), [`items[${n}][itemNote]`]: `Stratek sale #${tx.id}`, [`items[${n}][itemCategoryName]`]: 'Food & beverage' }));
        await cb(env, 'POST', '/postCustomItem', form);
        const room = g.rooms.join('/') || '?';
        await store.put(`tx:${tx.id}`, { reservation: g.id, guest: g.guest, room, at: new Date().toISOString() });
        return { type: 'status', title: 'Charged to room', status: `Room ${room}`, text: `${tx.currency} ${tx.amount} is on ${g.guest}'s Cloudbeds bill. A person settles the Stratek sale (the guest pays the hotel at check-out).` };
      },
    },
  ],
};

modules.integrations/coinbase.js:
// coinbase -- crypto payments through Coinbase Business checkouts (CDP API key).
// Docs: https://docs.cdp.coinbase.com/coinbase-business/
//
// Buttons
//   Test Coinbase (Integrations tab)        lists recent checkouts (checks the key)
//   Pay with crypto (under the QR)          POST /api/v1/checkouts -> QR of the hosted payment page
//   Check crypto payment (sale details)     GET /api/v1/checkouts/:id
//   Refund crypto payment (sale details)    POST /api/v1/checkouts/:id/refund
// Auth: each request carries a short-lived JWT signed with the CDP API key
// (Ed25519 keys; create one in the CDP portal with the "Ed25519" signature algorithm).
// Accepted currencies are set by Coinbase (e.g. USD, EUR, GBP, SGD, USDC) -- not NPR.

import { sale, b64url, b64urlText } from './_util.js';

const HOST = 'business.coinbase.com';

async function jwt(env, method, path) {
  const raw = Uint8Array.from(atob(String(env.COINBASE_API_PRIVATE_KEY).trim()), (c) => c.charCodeAt(0));
  if (raw.length !== 64) throw new Error('The Coinbase private key must be an Ed25519 key (base64, from the CDP portal). ECDSA keys are not supported yet.');
  const key = await crypto.subtle.importKey('jwk', { kty: 'OKP', crv: 'Ed25519', d: b64url(raw.slice(0, 32)), x: b64url(raw.slice(32)) }, { name: 'Ed25519' }, false, ['sign']);
  const now = Math.floor(Date.now() / 1000);
  const nonce = [...crypto.getRandomValues(new Uint8Array(16))].map((b) => b.toString(16).padStart(2, '0')).join('');
  const name = String(env.COINBASE_API_KEY_NAME).trim();
  const head = b64urlText(JSON.stringify({ alg: 'EdDSA', kid: name, typ: 'JWT', nonce }));
  const body = b64urlText(JSON.stringify({ sub: name, iss: 'cdp', nbf: now, exp: now + 120, uris: [`${method} ${HOST}${path}`] }));
  const sig = await crypto.subtle.sign({ name: 'Ed25519' }, key, new TextEncoder().encode(`${head}.${body}`));
  return `${head}.${body}.${b64url(sig)}`;
}

async function cb(env, method, path, bodyObj) {
  const res = await fetch(`https://${HOST}${path}`, {
    method,
    headers: { Authorization: `Bearer ${await jwt(env, method, path.split('?')[0])}`, 'Content-Type': 'application/json', Accept: 'application/json' },
    body: bodyObj ? JSON.stringify(bodyObj) : undefined,
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) {
    if (res.status === 401) throw new Error('Coinbase did not accept the API key. Check the key name and private key in Set up.');
    throw new Error(`Coinbase: ${data?.message || data?.error || `error ${res.status}`}`);
  }
  return data;
}

const STATUS = { COMPLETED: 'Paid', ACTIVE: 'Waiting', PROCESSING: 'Processing', EXPIRED: 'Expired', FAILED: 'Failed', DEACTIVATED: 'Cancelled', REFUNDED: 'Refunded', PARTIALLY_REFUNDED: 'Partly refunded' };

export default {
  id: 'coinbase',
  name: 'Coinbase (crypto)',
  category: 'payments',
  status: 'available',
  description: 'Crypto payments (e.g. USDC) through Coinbase Business checkouts.',
  docsUrl: 'https://docs.cdp.coinbase.com/coinbase-business/',
  test: { support: 'none', note: 'Coinbase Business checkouts have no test environment Stratek can rely on, so Coinbase runs with live keys only.' },
  secrets: [
    { name: 'COINBASE_API_KEY_NAME', label: 'CDP API key ID / name', hint: 'From the Coinbase Developer Platform portal (API keys). Use the Ed25519 signature algorithm.' },
    { name: 'COINBASE_API_PRIVATE_KEY', label: 'CDP API private key (Ed25519, base64)', hint: 'The "secret" shown once when the key is created.' },
  ],
  actions: [
    {
      id: 'test', label: 'Test Coinbase', placement: ['settings'], fields: [],
      async run({ env }) {
        const d = await cb(env, 'GET', '/api/v1/checkouts?pageSize=1');
        return { type: 'message', title: 'Coinbase is connected', text: `API key accepted${Array.isArray(d?.checkouts) ? ` (${d.checkouts.length ? 'has' : 'no'} earlier checkouts)` : ''}.` };
      },
    },
    {
      id: 'payment_link', label: 'Pay with crypto (Coinbase)', placement: ['charge'], fields: [],
      async run({ env, context, origin, store, claims }) {
        const tx = sale(context);
        const c = await cb(env, 'POST', '/api/v1/checkouts', {
          amount: Number(tx.amount).toFixed(2),
          currency: tx.currency,
          description: `${claims.owner_name || 'Shop'} -- sale #${tx.id}`.slice(0, 500),
          metadata: { stratek_transaction: tx.id },
          successRedirectUrl: `${origin}/paid`,
          failRedirectUrl: `${origin}/paid`,
        });
        await store.put(`tx:${tx.id}`, { checkoutId: c.id, amount: c.amount, currency: c.currency });
        return { type: 'qr', title: `Pay with crypto -- ${c.currency} ${c.amount}`, text: 'Customer scans this to pay with crypto. Then use "Check crypto payment" on the sale.', qrPayload: c.url };
      },
    },
    {
      id: 'check', label: 'Check crypto payment', placement: ['transaction'], fields: [],
      async run({ env, context, store }) {
        const tx = sale(context);
        const saved = await store.get(`tx:${tx.id}`);
        if (!saved) return { type: 'message', title: 'No crypto payment', text: 'No Coinbase payment was started for this sale.' };
        const c = await cb(env, 'GET', `/api/v1/checkouts/${encodeURIComponent(saved.checkoutId)}`);
        const paid = c.status === 'COMPLETED';
        return { type: 'status', title: 'Coinbase', status: STATUS[c.status] || c.status, text: paid ? `Paid${c.transactionHash ? ` (tx ${String(c.transactionHash).slice(0, 12)}...)` : ''}. Now press Settle on this sale.` : 'Not paid yet.' };
      },
    },
    {
      id: 'refund', outbound: true, label: 'Refund crypto payment', placement: ['transaction'],
      fields: [{ name: 'amount', label: 'Amount to refund (empty = all)', type: 'number' }],
      async run({ env, context, store, fields }) {
        const tx = sale(context);
        const saved = await store.get(`tx:${tx.id}`);
        if (!saved) throw new Error('No Coinbase payment was started for this sale.');
        const amount = fields.amount ? Number(fields.amount).toFixed(2) : saved.amount;
        const r = await cb(env, 'POST', `/api/v1/checkouts/${encodeURIComponent(saved.checkoutId)}/refund`, { amount: String(amount), currency: saved.currency, reason: 'Refund from Stratek POS' });
        return { type: 'status', title: 'Coinbase refund', status: r?.refund?.status || r?.checkout?.status || 'Requested', text: `Refund of ${saved.currency} ${amount} requested.` };
      },
    },
  ],
};

modules.integrations/connectips.js:
// connectips -- pay a sale from any Nepali bank account through NCHL connectIPS.
// The QR opens a short page on this connector that posts the signed form to connectIPS;
// after the customer pays, connectIPS sends them to the success/failure URL registered with
// NCHL (give NCHL: <connector>/pay/connectips/return/live -- /test for UAT). The connector then
// asks connectIPS (validatetxn) and tells Stratek (signed "payment.succeeded"; a person settles).
//   Login page:  <base>/connectipswebgw/loginpage          (form POST)
//   Validate:    <base>/connectipswebws/api/creditor/validatetxn  (basic auth APPID:password)
//   Token: base64( SHA256withRSA( "MERCHANTID=..,APPID=..,APPNAME=..,TXNID=..,TXNDATE=..,TXNCRNCY=NPR,
//          TXNAMT=..,REFERENCEID=..,REMARKS=..,PARTICULARS=..,TOKEN=TOKEN" ) ) with your CREDITOR key.
//   Docs: https://doc.connectips.com/docs/connectIPS-Gateway/merchant-interface
// Buttons: Test connectIPS (Integrations tab); Pay with connectIPS (under the payment QR);
// Check connectIPS payment (sale details). Refunds: through NCHL / your bank.

import { sale } from './_util.js';
import { paisa, rupees, requireNpr, randomToken, gatewayFormPage, resultPage, emitPaid } from './_nepal.js';

const DEFAULT_BASE = { live: 'https://login.connectips.com', test: 'https://uat.connectips.com' };
const base = (env, mode) => String(env.CONNECTIPS_BASE_URL || DEFAULT_BASE[mode === 'test' ? 'test' : 'live']).replace(/\/+$/, '');

// ── RSA key (PEM, PKCS#8 "BEGIN PRIVATE KEY" or PKCS#1 "BEGIN RSA PRIVATE KEY") ──
function derLen(n) { if (n < 128) return [n]; const b = []; while (n > 0) { b.unshift(n & 255); n >>= 8; } return [0x80 | b.length, ...b]; }
function pkcs1ToPkcs8(pkcs1) {
  const algo = [0x30, 0x0d, 0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01, 0x05, 0x00];
  const octet = [0x04, ...derLen(pkcs1.length), ...pkcs1];
  const body = [0x02, 0x01, 0x00, ...algo, ...octet];
  return new Uint8Array([0x30, ...derLen(body.length), ...body]);
}
export async function rsaKey(pem) {
  const s = String(pem || '');
  const isPkcs1 = /BEGIN RSA PRIVATE KEY/.test(s);
  if (!/PRIVATE KEY/.test(s)) throw new Error('connectIPS: paste your private key in PEM format (-----BEGIN PRIVATE KEY----- ...). Convert CREDITOR.pfx with: openssl pkcs12 -in CREDITOR.pfx -nocerts -nodes');
  const b64 = s.replace(/-----[^-]+-----/g, '').replace(/\s+/g, '');
  let der = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  if (isPkcs1) der = pkcs1ToPkcs8([...der]);
  try { return await crypto.subtle.importKey('pkcs8', der, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign']); }
  catch { throw new Error('connectIPS: that private key could not be read. Export it again from CREDITOR.pfx (unencrypted PEM).'); }
}
async function token(env, text) {
  const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', await rsaKey(env.CONNECTIPS_PRIVATE_KEY), new TextEncoder().encode(text));
  return btoa(String.fromCharCode(...new Uint8Array(sig)));
}

async function validate(env, mode, s) {
  const msg = `MERCHANTID=${env.CONNECTIPS_MERCHANT_ID},APPID=${env.CONNECTIPS_APP_ID},REFERENCEID=${s.txnId},TXNAMT=${s.amount}`;
  const res = await fetch(`${base(env, mode)}/connectipswebws/api/creditor/validatetxn`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Basic ${btoa(`${env.CONNECTIPS_APP_ID}:${env.CONNECTIPS_PASSWORD}`)}` },
    body: JSON.stringify({ merchantId: Number(env.CONNECTIPS_MERCHANT_ID), appId: env.CONNECTIPS_APP_ID, referenceId: s.txnId, txnAmt: String(s.amount), token: await token(env, msg) }),
  });
  const j = await res.json().catch(() => null);
  if (res.status === 401) throw new Error('connectIPS did not accept the App ID / password.');
  if (!res.ok && !j) throw new Error(`connectIPS answered ${res.status}.`);
  return j || {};
}

async function checkAndReport({ env, mode, store, emit, txId }) {
  const s = await store.get(`tx:${txId}`);
  if (!s) return { known: false };
  const j = await validate(env, mode, s);
  const ok = String(j.status || '').toUpperCase() === 'SUCCESS';
  await store.put(`tx:${txId}`, { ...s, status: ok ? 'SUCCESS' : (j.status || 'PENDING'), statusDesc: j.statusDesc || null });
  if (ok && !s.reported && emit) {
    await emitPaid(emit, { integration: 'connectips', provider: 'connectIPS', txId, amountPaisa: s.amount, ref: s.txnId, livemode: mode !== 'test' });
    await store.put(`tx:${txId}`, { ...s, status: 'SUCCESS', statusDesc: j.statusDesc || null, reported: true });
  }
  return { known: true, ok, status: j.status || 'PENDING', desc: j.statusDesc || '' };
}

const nepalDate = () => { const d = new Date(Date.now() + 345 * 60000); return `${String(d.getUTCDate()).padStart(2, '0')}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${d.getUTCFullYear()}`; };

export default {
  id: 'connectips',
  name: 'connectIPS',
  category: 'payments',
  status: 'available',
  color: '#0C4DA2',
  description: 'Pay a sale from any Nepali bank account with connectIPS; Stratek sees the payment.',
  docsUrl: 'https://doc.connectips.com/docs/connectIPS-Gateway/merchant-interface',
  test: { support: 'sandbox', note: 'NCHL gives UAT credentials and a UAT certificate for testing (uat.connectips.com).' },
  secrets: [
    { name: 'CONNECTIPS_MERCHANT_ID', label: 'Merchant ID', hint: 'From NCHL when your connectIPS e-payment is approved.' },
    { name: 'CONNECTIPS_APP_ID', label: 'App ID' },
    { name: 'CONNECTIPS_APP_NAME', label: 'App name' },
    { name: 'CONNECTIPS_PASSWORD', label: 'App password', hint: 'Used to check payments (validatetxn).' },
    { name: 'CONNECTIPS_PRIVATE_KEY', label: 'Private key (PEM)', hint: 'From your CREDITOR.pfx: openssl pkcs12 -in CREDITOR.pfx -nocerts -nodes -- paste the PRIVATE KEY block (BEGIN/END lines included).' },
    { name: 'CONNECTIPS_BASE_URL', label: 'connectIPS address', hint: 'Optional. Leave empty for https://login.connectips.com (Live) / https://uat.connectips.com (Test), or paste the address NCHL gave you.', optional: true },
  ],
  async payPage({ token: t, env, mode, store }) {
    const txId = t && (await store.get(`start:${t}`));
    const s = txId && (await store.get(`tx:${txId}`));
    if (!s || s.token !== t) return resultPage(false, 'This payment link has expired. Ask the shop for a new QR.');
    if (s.status === 'SUCCESS') return resultPage(true, 'This sale is already paid.');
    const f = {
      MERCHANTID: env.CONNECTIPS_MERCHANT_ID, APPID: env.CONNECTIPS_APP_ID, APPNAME: env.CONNECTIPS_APP_NAME, TXNID: s.txnId, TXNDATE: s.txnDate,
      TXNCRNCY: 'NPR', TXNAMT: String(s.amount), REFERENCEID: s.ref, REMARKS: s.remarks, PARTICULARS: s.particulars,
    };
    f.TOKEN = await token(env, `${Object.entries(f).map(([k, v]) => `${k}=${v}`).join(',')},TOKEN=TOKEN`);
    return gatewayFormPage({ title: 'Pay with connectIPS', amountText: `Rs ${rupees(s.amount)}`, action: `${base(env, mode)}/connectipswebgw/loginpage`, fields: f, buttonLabel: 'Continue to connectIPS' });
  },
  async payReturn({ url, form, env, mode, store, emit }) {
    const txnId = url.searchParams.get('TXNID') || form.TXNID;
    const txId = txnId && (await store.get(`txn:${txnId}`));
    if (!txId) return resultPage(false);
    const r = await checkAndReport({ env, mode, store, emit, txId });
    return r.ok ? resultPage(true) : resultPage(false, r.desc || undefined);
  },
  actions: [
    {
      id: 'test', label: 'Test connectIPS', placement: ['settings'], fields: [],
      async run({ env, origin, mode }) {
        await rsaKey(env.CONNECTIPS_PRIVATE_KEY);
        return { type: 'message', title: 'connectIPS keys look right', text: `The private key reads fine. Give NCHL this success and failure URL: ${origin}/pay/connectips/return/${mode}. Then make one small payment to confirm.` };
      },
    },
    {
      id: 'payment_link', label: 'Pay with connectIPS', placement: ['charge'], fields: [],
      async run({ env, context, origin, store, mode, claims }) {
        const tx = sale(context);
        requireNpr(tx, 'connectIPS');
        await rsaKey(env.CONNECTIPS_PRIVATE_KEY); // fail early, at the till, if the key is wrong
        const amount = paisa(tx.amount);
        const t = randomToken();
        const txnId = `S${tx.id}T${Date.now().toString(36)}`.slice(0, 20);
        const old = await store.get(`tx:${tx.id}`);
        if (old?.token) await store.delete(`start:${old.token}`);
        await store.put(`tx:${tx.id}`, { token: t, txnId, amount, txnDate: nepalDate(), ref: `sale-${tx.id}`.slice(0, 20), remarks: `Sale #${tx.id}`.slice(0, 50), particulars: `${claims?.owner_name || 'Shop'} sale #${tx.id}`.slice(0, 100), status: 'PENDING', createdAt: new Date().toISOString() });
        await store.put(`start:${t}`, tx.id);
        await store.put(`txn:${txnId}`, tx.id);
        return { type: 'qr', title: `Pay with connectIPS -- Rs ${rupees(amount)}`, text: `The customer scans this and pays from their bank account${mode === 'test' ? ' (TEST, UAT)' : ''}. Stratek sees the payment when they finish.`, qrPayload: `${origin}/pay/connectips/start/${mode}/${t}` };
      },
    },
    {
      id: 'check', label: 'Check connectIPS payment', placement: ['transaction'], fields: [],
      async run({ env, context, store, mode, emit }) {
        const tx = sale(context);
        const r = await checkAndReport({ env, mode, store, emit, txId: tx.id });
        if (!r.known) return { type: 'message', title: 'No connectIPS payment', text: 'No connectIPS payment was started for this sale.' };
        return { type: 'status', title: 'connectIPS', status: r.ok ? 'Paid' : r.status, text: r.ok ? 'The customer has paid with connectIPS. Now press Settle on this sale.' : (r.desc || 'Not paid yet.') };
      },
    },
  ],
};

