modules.integrations/meta_capi.js:
// meta_capi -- send sales to Meta (Facebook / Instagram Ads) as Purchase events
// with the Conversions API, so ads that brought customers in get the credit.
// Docs: https://developers.facebook.com/docs/marketing-api/conversions-api
//
// Buttons
//   Test Meta Conversions API (Integrations tab)  reads the pixel/dataset name
//   Send sale to Meta Ads (sale details)          POST /{pixel}/events (event Purchase,
//                                                 action_source physical_store)
// Customer email/phone are SHA-256 hashed before they leave the connector, as Meta requires.

import { sale, sha256Hex } from './_util.js';

const graph = (env) => `https://graph.facebook.com/${String(env.META_GRAPH_VERSION || 'v23.0').trim()}`;

async function meta(env, method, path, body) {
  const url = new URL(graph(env) + path);
  url.searchParams.set('access_token', env.META_CAPI_TOKEN);
  const res = await fetch(url, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(`Meta: ${data?.error?.error_user_msg || data?.error?.message || `error ${res.status}`}`);
  return data;
}

export default {
  id: 'meta_capi',
  name: 'Meta Conversions API',
  category: 'marketing',
  status: 'available',
  description: 'Send each sale to Meta (Facebook/Instagram Ads) as a Purchase event so ad results are measured.',
  docsUrl: 'https://developers.facebook.com/docs/marketing-api/conversions-api',
  test: {
    support: 'sandbox',
    note: 'Test events use the same dataset and token plus a test event code; they appear in Events Manager -> Test events only.',
    extraSecrets: [{ name: 'META_TEST_EVENT_CODE', label: 'Test event code', hint: 'Events Manager -> your dataset -> Test events (e.g. TEST12345).' }],
  },
  secrets: [
    { name: 'META_PIXEL_ID', label: 'Pixel / dataset ID', hint: 'Events Manager -> your dataset -> Settings.' },
    { name: 'META_CAPI_TOKEN', label: 'Conversions API access token', hint: 'Events Manager -> Settings -> Conversions API -> Generate access token.' },
    { name: 'META_GRAPH_VERSION', label: 'Graph API version', hint: 'Leave empty for v23.0.', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test Meta Conversions API', placement: ['settings'], fields: [],
      async run({ env }) {
        const d = await meta(env, 'GET', `/${encodeURIComponent(env.META_PIXEL_ID)}?fields=name,id`);
        return { type: 'message', title: 'Meta is connected', text: `Dataset "${d.name || d.id}"${env.META_TEST_EVENT_CODE ? ' -- test mode (events show under Test events)' : ''}.` };
      },
    },
    {
      id: 'send_purchase', label: 'Send sale to Meta Ads', placement: ['transaction'],
      fields: [
        { name: 'email', label: 'Customer email (email or phone needed)', type: 'email' },
        { name: 'phone', label: 'Customer phone, with country code (e.g. 9779800000000)', type: 'tel' },
      ],
      async run({ env, context, store, fields }) {
        const tx = sale(context);
        const email = String(fields.email || '').trim().toLowerCase();
        const phone = String(fields.phone || '').replace(/\D/g, '');
        if (!email && !phone) throw new Error("Meta needs the customer's email or phone to match the sale.");
        const user_data = {};
        if (email) user_data.em = [await sha256Hex(email)];
        if (phone) user_data.ph = [await sha256Hex(phone)];
        const items = Array.isArray(tx.items) ? tx.items : [];
        const event = {
          event_name: 'Purchase',
          event_time: Math.floor(new Date(tx.createdAt || Date.now()).getTime() / 1000) || Math.floor(Date.now() / 1000),
          event_id: `stratek-${tx.id}`,
          action_source: 'physical_store',
          user_data,
          custom_data: { currency: tx.currency, value: Number(tx.amount), order_id: tx.id, contents: items.map((i) => ({ id: String(i.name).slice(0, 100), quantity: Number(i.qty) || 1, item_price: Number(i.price) || undefined })) },
        };
        const d = await meta(env, 'POST', `/${encodeURIComponent(env.META_PIXEL_ID)}/events`, { data: [event], ...(env.STRATEK_MODE === 'test' && env.META_TEST_EVENT_CODE ? { test_event_code: env.META_TEST_EVENT_CODE } : {}) });
        await store.put(`tx:${tx.id}`, { sentAt: new Date().toISOString() });
        return { type: 'message', title: 'Sent to Meta', text: `Purchase of ${tx.currency} ${tx.amount} sent (${d.events_received ?? 1} event${env.META_TEST_EVENT_CODE ? ', test mode' : ''}).` };
      },
    },
  ],
};

modules.integrations/meta_catalog.js:
// meta_catalog -- keep a Facebook / Instagram Shop catalogue in step with the
// Stratek menu (Catalog Batch API).
// Docs: https://developers.facebook.com/docs/marketing-api/catalog-batch/
//
// Buttons (Integrations tab)
//   Test Meta Catalog        reads the catalogue name and product count
//   Sync menu to Facebook/Instagram Shop
//                            upserts every menu item that has a photo (Meta requires an
//                            image); items marked unavailable are "out of stock".
// Stratek sends the menu with the request (the connector can't read Stratek on its own).

import { toMinor } from './_util.js';

const graph = (env) => `https://graph.facebook.com/${String(env.META_GRAPH_VERSION || 'v23.0').trim()}`;

async function meta(env, method, path, body) {
  const url = new URL(graph(env) + path);
  url.searchParams.set('access_token', env.META_SYSTEM_USER_TOKEN);
  const res = await fetch(url, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(`Meta: ${data?.error?.error_user_msg || data?.error?.message || `error ${res.status}`}`);
  return data;
}

export default {
  id: 'meta_catalog',
  name: 'Meta Catalog (Facebook & Instagram Shop)',
  category: 'commerce',
  status: 'available',
  description: 'Keep a Facebook/Instagram shop catalogue in step with the POS menu.',
  docsUrl: 'https://developers.facebook.com/docs/marketing-api/catalog-batch/',
  test: { support: 'sandbox', note: 'Meta has no catalogue sandbox: put the ID of a separate test catalogue in Test keys.', hints: { META_CATALOG_ID: 'ID of a separate TEST catalogue (Commerce Manager -> create a catalogue just for testing).' } },
  secrets: [
    { name: 'META_CATALOG_ID', label: 'Catalog ID', hint: 'Commerce Manager -> your catalogue -> Settings.' },
    { name: 'META_SYSTEM_USER_TOKEN', label: 'System user access token', hint: 'Business Settings -> System users -> Generate token with catalog_management.' },
    { name: 'META_SHOP_URL', label: 'Shop web address', hint: 'Link shown on each product (e.g. your website or Instagram). Leave empty to use Stratek.', optional: true },
    { name: 'META_GRAPH_VERSION', label: 'Graph API version', hint: 'Leave empty for v23.0.', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test Meta Catalog', placement: ['settings'], fields: [],
      async run({ env }) {
        const d = await meta(env, 'GET', `/${encodeURIComponent(env.META_CATALOG_ID)}?fields=name,product_count`);
        return { type: 'message', title: 'Meta Catalog is connected', text: `Catalogue "${d.name}" has ${d.product_count ?? '?'} products.` };
      },
    },
    {
      id: 'sync_menu', label: 'Sync menu to Facebook/Instagram Shop', placement: ['settings'], fields: [],
      context: ['menu'], // Stratek sends { menu: { currency, items: [...] } }
      async run({ env, context, claims }) {
        const menu = context?.menu;
        if (!menu || !Array.isArray(menu.items)) throw new Error('Run this from a shop\'s Integrations tab (it needs the shop\'s menu).');
        const currency = String(menu.currency || 'NPR').toUpperCase();
        const link = env.META_SHOP_URL || claims.iss || 'https://strateknepal.com';
        const withPhoto = menu.items.filter((i) => /^https:\/\//.test(i.photo || ''));
        if (!withPhoto.length) throw new Error('None of your menu items has a photo -- Meta needs one per product.');
        const requests = withPhoto.slice(0, 5000).map((i) => ({
          method: 'UPDATE',
          retailer_id: `stratek-${i.id}`,
          data: {
            name: String(i.name).slice(0, 150),
            description: String(i.description || i.name).slice(0, 5000),
            price: toMinor(i.price, currency),
            currency,
            availability: i.available === false ? 'out of stock' : 'in stock',
            condition: 'new',
            image_url: i.photo,
            url: link,
            ...(i.category ? { category: String(i.category).slice(0, 250) } : {}),
          },
        }));
        let sent = 0;
        for (let k = 0; k < requests.length; k += 1000) {
          await meta(env, 'POST', `/${encodeURIComponent(env.META_CATALOG_ID)}/batch`, { allow_upsert: true, requests: requests.slice(k, k + 1000) });
          sent += Math.min(1000, requests.length - k);
        }
        const skipped = menu.items.length - withPhoto.length;
        return { type: 'message', title: 'Menu sent to Meta', text: `${sent} product(s) sent${skipped ? `; ${skipped} skipped (no photo)` : ''}. Meta processes them in a few minutes -- check Commerce Manager.` };
      },
    },
  ],
};

