modules.integrations/shipbob.js:
// shipbob -- have ShipBob's warehouses pick, pack and ship a sale from your stock there.
// ShipBob dashboard -> Integrations -> API tokens -> generate a Personal Access Token.
// A sandbox account (developer.shipbob.com/sandbox) gives a separate token for Test keys.
// Products are matched by SKU: the sale items' SKUs, or type them on the button.
//   API: https://api.shipbob.com (test: https://sandbox-api.shipbob.com), version 2025-07
//        GET /channel, POST /order (header shipbob_channel_id), GET /order/{id}/shipment
// Buttons: Test ShipBob (Integrations tab); Fulfil with ShipBob (needs a person -- ShipBob
// charges for fulfilment), ShipBob tracking (sale details).

import { sale } from './_util.js';
import { recipientFields, recipient, skuLines, skuField, shipmentFor, rememberShipment, noShipment, readJson } from './_ship.js';

const VERSION = '2025-07';
const base = (mode) => (mode === 'test' ? 'https://sandbox-api.shipbob.com' : 'https://api.shipbob.com');

async function sb(env, mode, method, path, body, channel) {
  const res = await fetch(`${base(mode)}/${VERSION}${path}`, { method, headers: { Authorization: `Bearer ${String(env.SHIPBOB_TOKEN).trim()}`, Accept: 'application/json', ...(channel ? { shipbob_channel_id: String(channel) } : {}), ...(body ? { 'Content-Type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined });
  const j = await readJson(res);
  if (res.status === 401) throw new Error('ShipBob did not accept the token (sandbox and live tokens are different).');
  if (!res.ok) {
    const errs = j?.errors ? Object.entries(j.errors).map(([k, v]) => `${k}: ${[].concat(v).join(', ')}`).join('; ') : '';
    throw new Error(`ShipBob: ${errs || j?.title || j?.message || j?._text || `error ${res.status}`}`.slice(0, 300));
  }
  return j;
}

async function channelId(env, store, mode) {
  if (env.SHIPBOB_CHANNEL_ID) return String(env.SHIPBOB_CHANNEL_ID).trim();
  const key = `channel:${mode}`;
  const have = await store.get(key);
  if (have) return have;
  const list = [].concat(await sb(env, mode, 'GET', '/channel'));
  const c = list.find((x) => (x.scopes || []).some((s) => /orders_write/.test(s))) || list[0];
  if (!c?.id) throw new Error('ShipBob: this token has no channel. Generate the token with order access.');
  await store.put(key, String(c.id));
  return String(c.id);
}

export default {
  id: 'shipbob',
  name: 'ShipBob',
  category: 'fulfilment',
  status: 'available',
  color: '#1E62EC',
  description: 'ShipBob warehouses pick, pack and ship your sales from your stock there.',
  docsUrl: 'https://developer.shipbob.com/',
  test: { support: 'sandbox', note: 'A ShipBob sandbox account has its own token; sandbox orders are not shipped.' },
  secrets: [
    { name: 'SHIPBOB_TOKEN', label: 'ShipBob Personal Access Token', hint: 'ShipBob -> Integrations -> API tokens -> Generate.' },
    { name: 'SHIPBOB_SHIPPING_METHOD', label: 'Ship option', hint: 'Optional, default Standard (must match a Ship Option in ShipBob).', optional: true },
    { name: 'SHIPBOB_CHANNEL_ID', label: 'Channel ID', hint: 'Optional; found automatically.', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test ShipBob', placement: ['settings'], fields: [],
      async run({ env, store, mode }) {
        const id = await channelId(env, store, mode);
        return { type: 'message', title: 'ShipBob is connected', text: `Orders will go to channel ${id}${mode === 'test' ? ' (sandbox)' : ''}.` };
      },
    },
    {
      id: 'create_order', outbound: true, label: 'Fulfil with ShipBob', placement: ['transaction'], fields: [...recipientFields({ state: true, weight: false }), skuField],
      async run({ env, fields, context, store, mode }) {
        const tx = sale(context);
        const had = await shipmentFor(store, tx);
        if (had?.orderId) return { type: 'status', title: 'ShipBob', status: 'Already sent', text: `Order ${had.orderId} for sale #${tx.id}.` };
        const to = recipient(fields, context);
        const items = skuLines(fields.skus, tx);
        const o = await sb(env, mode, 'POST', '/order', {
          reference_id: `stratek-${tx.id}`, order_number: `S${tx.id}`, type: 'DTC',
          shipping_method: String(env.SHIPBOB_SHIPPING_METHOD || 'Standard').trim(), purchase_date: new Date().toISOString(),
          recipient: { name: to.name, phone_number: to.phone, ...(to.email ? { email: to.email } : {}), address: { address1: to.address, city: to.city, ...(to.state ? { state: to.state } : {}), zip_code: to.postalCode, country: to.country } },
          products: items.map((i) => ({ reference_id: i.sku, quantity: i.qty, ...(i.name ? { name: i.name } : {}), ...(i.price ? { unit_price: i.price } : {}) })),
          tags: [{ name: 'source', value: 'stratek' }],
        }, await channelId(env, store, mode));
        await rememberShipment(store, tx, { orderId: o.id });
        return { type: 'status', title: 'ShipBob', status: o.status || 'Processing', text: `Order ${o.id}${mode === 'test' ? ' (sandbox)' : ''} -- ${items.map((i) => `${i.sku} x${i.qty}`).join(', ')}.` };
      },
    },
    {
      id: 'track', label: 'ShipBob tracking', placement: ['transaction'], fields: [],
      async run({ env, context, store, mode }) {
        const tx = sale(context);
        const had = await shipmentFor(store, tx);
        if (!had?.orderId) return noShipment('ShipBob');
        const list = [].concat(await sb(env, mode, 'GET', `/order/${encodeURIComponent(had.orderId)}/shipment`));
        const s = list[0] || {};
        const t = s.tracking || {};
        return { type: 'status', title: `ShipBob order ${had.orderId}`, status: s.status || 'Processing', text: [t.carrier, t.tracking_number, t.tracking_url].filter(Boolean).join(' · ') || 'Not shipped yet.' };
      },
    },
  ],
};

modules.integrations/shiprocket.js:
// shiprocket -- ship across India with Shiprocket (for shops selling in INR).
// Shiprocket -> Settings -> API -> Configure -> create an API user (a separate email from
// your login). Add your pickup address in Shiprocket first and put its nickname below.
//   API: https://apiv2.shiprocket.in/v1/external
//        POST /auth/login (token, 10 days), GET /courier/serviceability/, POST /orders/create/adhoc,
//        POST /courier/assign/awb, POST /courier/generate/label, GET /courier/track/awb/{awb}
// Buttons (sale details): Check Shiprocket couriers, Ship with Shiprocket (needs a person --
// it pays for the courier from your Shiprocket wallet), Track Shiprocket shipment.

import { sale } from './_util.js';
import { kg, recipientFields, recipient, lines, shipmentFor, rememberShipment, bookedResult, noShipment, readJson } from './_ship.js';

const BASE = 'https://apiv2.shiprocket.in/v1/external';

async function token(env, store, fresh = false) {
  const have = await store.get('token');
  const who = String(env.SHIPROCKET_EMAIL).trim().toLowerCase();
  if (!fresh && have?.token && have.who === who && have.exp > Date.now()) return have.token;
  const res = await fetch(`${BASE}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: who, password: String(env.SHIPROCKET_PASSWORD) }) });
  const j = await readJson(res);
  if (!res.ok || !j?.token) throw new Error('Shiprocket did not accept the API user email / password (use the API user, not your login).');
  await store.put('token', { token: j.token, who, exp: Date.now() + 9 * 86400000 });
  return j.token;
}

async function sr(env, store, method, path, body) {
  const call = async (t) => fetch(`${BASE}${path}`, { method, headers: { Authorization: `Bearer ${t}`, Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined });
  let res = await call(await token(env, store));
  if (res.status === 401) res = await call(await token(env, store, true));
  const j = await readJson(res);
  if (!res.ok || j?.status_code >= 400) {
    const errs = j?.errors ? Object.values(j.errors).flat().join('; ') : '';
    throw new Error(`Shiprocket: ${errs || j?.message || `error ${res.status}`}`.slice(0, 300));
  }
  return j;
}

const pin = (v, what) => { const p = String(v || '').replace(/\s/g, ''); if (!/^\d{6}$/.test(p)) throw new Error(`${what}: use the 6-digit PIN code.`); return p; };
const inrOnly = (tx) => { if (tx.currency !== 'INR') throw new Error('Shiprocket ships within India -- this sale is not in INR.'); };
const nowIst = () => new Date(Date.now() + 330 * 60000).toISOString().slice(0, 16).replace('T', ' ');

export default {
  id: 'shiprocket',
  name: 'Shiprocket',
  category: 'delivery',
  status: 'available',
  color: '#7B3FE4',
  description: 'Ship orders across India with Shiprocket (for INR shops).',
  docsUrl: 'https://apidocs.shiprocket.in/',
  test: { support: 'none', note: 'Shiprocket has no test mode; cancel test orders in Shiprocket before a courier is assigned.' },
  secrets: [
    { name: 'SHIPROCKET_EMAIL', label: 'Shiprocket API user email', hint: 'Shiprocket -> Settings -> API -> Configure -> Create an API user.' },
    { name: 'SHIPROCKET_PASSWORD', label: 'Shiprocket API user password' },
    { name: 'SHIPROCKET_PICKUP_LOCATION', label: 'Pickup location nickname', hint: 'Settings -> Pickup addresses -> the nickname, e.g. Primary.' },
    { name: 'SHIPROCKET_PICKUP_PINCODE', label: 'Pickup PIN code', hint: 'For courier checks, e.g. 110001.' },
  ],
  actions: [
    {
      id: 'quote', label: 'Check Shiprocket couriers', placement: ['transaction'],
      fields: [{ name: 'weight', label: 'Weight (kg)', type: 'number', required: true }, { name: 'recipientPostalCode', label: 'Delivery PIN code', type: 'text', required: true }],
      async run({ env, fields, store }) {
        const q = new URLSearchParams({ pickup_postcode: pin(env.SHIPROCKET_PICKUP_PINCODE, 'Pickup'), delivery_postcode: pin(fields.recipientPostalCode, 'Delivery'), weight: String(kg(fields.weight, 100)), cod: '0' });
        const j = await sr(env, store, 'GET', `/courier/serviceability/?${q}`);
        const list = (j.data?.available_courier_companies || []).sort((a, b) => Number(a.rate) - Number(b.rate)).slice(0, 5);
        return { type: 'message', title: 'Shiprocket couriers', text: list.length ? list.map((c) => `${c.courier_name}: INR ${c.rate}${c.etd ? `, by ${c.etd}` : ''}`).join(' · ') : 'No courier serves this PIN code.' };
      },
    },
    {
      id: 'create_shipment', outbound: true, label: 'Ship with Shiprocket', placement: ['transaction'],
      fields: [...recipientFields({ state: true }).map((f) => (f.name === 'recipientPostalCode' ? { ...f, label: 'PIN code', required: true } : f.name === 'country' ? { ...f, label: 'Country code (default IN)', required: false } : f))],
      async run({ env, fields, context, store }) {
        const tx = sale(context); inrOnly(tx);
        const had = await shipmentFor(store, tx);
        if (had?.awb) return bookedResult({ carrier: 'Shiprocket', number: had.awb, labelUrl: had.labelUrl, mode: 'live', extra: '(already booked for this sale)' });
        const to = recipient({ ...fields, country: fields.country || 'IN' }, context);
        if (to.country !== 'IN') throw new Error('Shiprocket ships within India (country IN).');
        const [first, ...rest] = to.name.split(/\s+/);
        let s = had;
        if (!s?.shipmentId) {
          const o = await sr(env, store, 'POST', '/orders/create/adhoc', {
            order_id: `S${tx.id}`, order_date: nowIst(), pickup_location: String(env.SHIPROCKET_PICKUP_LOCATION || 'Primary').trim(),
            billing_customer_name: first, billing_last_name: rest.join(' '), billing_address: to.address, billing_city: to.city,
            billing_pincode: pin(to.postalCode, 'Delivery'), billing_state: to.state || to.city, billing_country: 'India',
            billing_email: to.email || undefined, billing_phone: to.phone.replace(/\D/g, '').slice(-10), shipping_is_billing: true,
            order_items: lines(tx).map((i, n) => ({ name: String(i.name).slice(0, 100), sku: String(i.sku || `stratek-${i.id ?? n + 1}`), units: Number(i.qty || 1), selling_price: Number(i.price) })),
            payment_method: 'Prepaid', sub_total: Number(tx.amount), length: 20, breadth: 15, height: 10, weight: kg(fields.weight, 100),
          });
          s = { orderId: o.order_id, shipmentId: o.shipment_id };
          await rememberShipment(store, tx, s);
        }
        const a = await sr(env, store, 'POST', '/courier/assign/awb', { shipment_id: s.shipmentId });
        const d = a.response?.data || {};
        if (!d.awb_code) throw new Error(`Shiprocket could not assign a courier${a.message ? `: ${a.message}` : ''} (check your wallet balance). The order is saved -- press again to retry.`);
        const l = await sr(env, store, 'POST', '/courier/generate/label', { shipment_id: [s.shipmentId] }).catch(() => ({}));
        const labelUrl = /^https:\/\//.test(l.label_url || '') ? l.label_url : null;
        await rememberShipment(store, tx, { ...s, awb: d.awb_code, courier: d.courier_name, labelUrl });
        return bookedResult({ carrier: 'Shiprocket', number: d.awb_code, labelUrl, mode: 'live', extra: d.courier_name ? `Courier: ${d.courier_name}.` : '' });
      },
    },
    {
      id: 'track', label: 'Track Shiprocket shipment', placement: ['transaction'], fields: [],
      async run({ env, context, store }) {
        const tx = sale(context);
        const s = await shipmentFor(store, tx);
        if (!s?.awb) return noShipment('Shiprocket');
        const j = await sr(env, store, 'GET', `/courier/track/awb/${encodeURIComponent(s.awb)}`);
        const t = j.tracking_data || {};
        const cur = t.shipment_track?.[0] || {};
        const act = t.shipment_track_activities?.[0] || {};
        return { type: 'status', title: `Shiprocket ${s.awb}`, status: cur.current_status || 'In the system', text: [s.courier, act.activity, act.location, cur.edd && `arrives ${cur.edd}`].filter(Boolean).join(' · ') };
      },
    },
  ],
};

modules.integrations/shipstation.js:
// shipstation -- send sales to ShipStation as orders to pick, pack and label there, and see
// the tracking number once it ships. ShipStation -> Settings -> Account -> API Settings ->
// API key and secret (legacy API, any paid plan).
//   API: https://ssapi.shipstation.com (basic auth key:secret)
//        GET /stores (test), POST /orders/createorder, GET /shipments?orderNumber=
// Buttons: Test ShipStation (Integrations tab); Send order to ShipStation, ShipStation tracking
// (sale details). Sending an order costs nothing -- labels are bought inside ShipStation.

import { sale } from './_util.js';
import { recipientFields, recipient, skuLines, skuField, shipmentFor, rememberShipment, noShipment, readJson } from './_ship.js';

async function ss(env, method, path, body) {
  const res = await fetch(`https://ssapi.shipstation.com${path}`, { method, headers: { Authorization: `Basic ${btoa(`${String(env.SHIPSTATION_API_KEY).trim()}:${String(env.SHIPSTATION_API_SECRET).trim()}`)}`, Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined });
  const j = await readJson(res);
  if (res.status === 401) throw new Error('ShipStation did not accept the API key / secret.');
  if (res.status === 429) throw new Error('ShipStation: too many requests this minute -- try again shortly.');
  if (!res.ok) throw new Error(`ShipStation: ${j?.ExceptionMessage || j?.Message || j?._text || `error ${res.status}`}`);
  return j;
}

export default {
  id: 'shipstation',
  name: 'ShipStation',
  category: 'fulfilment',
  status: 'available',
  color: '#84C225',
  description: 'Send sales to ShipStation to pick, pack and label, and see the tracking number.',
  docsUrl: 'https://www.shipstation.com/docs/api/',
  test: { support: 'none', note: 'ShipStation has no test mode; mark test orders cancelled in ShipStation.' },
  secrets: [
    { name: 'SHIPSTATION_API_KEY', label: 'ShipStation API key', hint: 'ShipStation -> Settings -> Account -> API Settings.' },
    { name: 'SHIPSTATION_API_SECRET', label: 'ShipStation API secret' },
    { name: 'SHIPSTATION_STORE_ID', label: 'Store ID', hint: 'Optional: which ShipStation store the orders go to ("Test ShipStation" lists them).', optional: true },
  ],
  actions: [
    {
      id: 'test', label: 'Test ShipStation', placement: ['settings'], fields: [],
      async run({ env }) {
        const stores = await ss(env, 'GET', '/stores?showInactive=false');
        return { type: 'message', title: 'ShipStation is connected', text: stores?.length ? `Stores: ${stores.slice(0, 6).map((s) => `${s.storeName} (ID ${s.storeId})`).join(', ')}.` : 'Connected (no stores yet).' };
      },
    },
    {
      id: 'send_order', label: 'Send order to ShipStation', placement: ['transaction'], fields: [...recipientFields({ state: true, weight: false }), { name: 'weight', label: 'Weight (kg, optional)', type: 'number' }, skuField],
      async run({ env, fields, context, store }) {
        const tx = sale(context);
        const had = await shipmentFor(store, tx);
        if (had?.orderId) return { type: 'message', title: 'Already in ShipStation', text: `Order S${tx.id} (ShipStation ID ${had.orderId}).` };
        const to = recipient(fields, context);
        const items = skuLines(fields.skus, tx);
        const address = { name: to.name, phone: to.phone, street1: to.address, city: to.city, state: to.state || null, postalCode: to.postalCode || null, country: to.country };
        const w = Number(fields.weight);
        const o = await ss(env, 'POST', '/orders/createorder', {
          orderNumber: `S${tx.id}`, orderKey: `stratek-${tx.id}`, orderDate: new Date().toISOString(), orderStatus: 'awaiting_shipment',
          customerEmail: to.email || null, billTo: address, shipTo: address,
          items: items.map((i) => ({ sku: i.sku, name: i.name || i.sku, quantity: i.qty, unitPrice: i.price })),
          amountPaid: Number(tx.amount), internalNotes: `From Stratek sale #${tx.id}`,
          ...(w > 0 ? { weight: { value: Math.round(w * 1000), units: 'grams' } } : {}),
          ...(env.SHIPSTATION_STORE_ID ? { advancedOptions: { storeId: Number(env.SHIPSTATION_STORE_ID) } } : {}),
        });
        await rememberShipment(store, tx, { orderId: o.orderId, orderNumber: o.orderNumber });
        return { type: 'message', title: 'Sent to ShipStation', text: `Order ${o.orderNumber} is waiting to ship (${items.length} line${items.length === 1 ? '' : 's'}).` };
      },
    },
    {
      id: 'track', label: 'ShipStation tracking', placement: ['transaction'], fields: [],
      async run({ env, context, store }) {
        const tx = sale(context);
        const had = await shipmentFor(store, tx);
        if (!had?.orderId) return noShipment('ShipStation');
        const j = await ss(env, 'GET', `/shipments?orderNumber=${encodeURIComponent(had.orderNumber || `S${tx.id}`)}`);
        const s = (j.shipments || []).filter((x) => !x.voided)[0];
        if (!s) return { type: 'status', title: `ShipStation ${had.orderNumber}`, status: 'Awaiting shipment', text: 'No label yet.' };
        return { type: 'status', title: `ShipStation ${had.orderNumber}`, status: 'Shipped', text: [s.carrierCode, s.trackingNumber, s.shipDate].filter(Boolean).join(' · ') };
      },
    },
  ],
};

