// pages.js -- the few pages a person sees when opening the connector's address.

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

export function page(title, bodyHtml, status = 200, extraHeaders = {}) {
  return new Response(`<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex"><meta name="referrer" content="no-referrer">
<title>${esc(title)} -- Stratek connector</title>
<style>
  body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; background: #fdecec; color: #201414; }
  main { max-width: 520px; margin: 8vh auto; background: #fff; border: 1px solid #e6caca; border-radius: 14px; padding: 32px 28px; box-shadow: 0 10px 30px rgba(92,15,22,.08); }
  .brand { font-weight: 700; color: #c81e2c; letter-spacing: .02em; margin-bottom: 18px; }
  h1 { font-size: 1.4rem; margin: 0 0 10px; }
  p { line-height: 1.55; color: #574646; }
  .btn { display: inline-block; background: #c81e2c; color: #fff; text-decoration: none; font-weight: 700; padding: 12px 22px; border-radius: 999px; margin-top: 8px; }
  .ok { background: #e7f6ec; color: #1e7a3e; border-radius: 8px; padding: 10px 14px; }
  .err { background: #fbeceb; color: #b3261e; border-radius: 8px; padding: 10px 14px; }
  label { display: block; font-weight: 600; margin: 14px 0 4px; }
  input[type=password], input[type=text] { width: 100%; box-sizing: border-box; padding: 10px 12px; border: 1px solid #e6caca; border-radius: 8px; font: inherit; }
  .hint { font-size: .85rem; color: #574646; margin-top: 4px; }
  .saved { font-size: .85rem; color: #1e7a3e; margin-top: 4px; }
  button.btn { border: 0; cursor: pointer; font: inherit; font-weight: 700; }
  .rm { font-weight: 400; display: inline; margin-left: 8px; font-size: .85rem; }
  code { background: #fdecec; padding: 2px 6px; border-radius: 4px; }
  small { color: #574646; }
</style></head>
<body><main><div class="brand">&#9679; Stratek connector</div>${bodyHtml}</main></body></html>`, {
    status,
    headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer', 'X-Frame-Options': 'DENY', ...extraHeaders },
  });
}

export function homePage({ pairing, version, stratekUrl }) {
  if (!pairing) {
    return page('Connect', `
      <h1>Connect this connector to Stratek</h1>
      <p>This connector is deployed and running. Connect it to your Stratek account so your integrations (like Pathao) show up in the POS.</p>
      <p><a class="btn" href="/connect">Connect to Stratek</a></p>
      <p><small>You'll be asked to sign in to Stratek and approve. Version ${esc(version)}.</small></p>`);
  }
  const back = pairing.ownerType === 'admin' ? `${stratekUrl}/admin.html#integrations` : `${stratekUrl}/dashboard.html#integrations`;
  return page('Connected', `
    <h1>Connected</h1>
    <p class="ok">This connector belongs to <strong>${esc(pairing.ownerName || pairing.ownerType)}</strong> on Stratek.</p>
    <p>Manage integrations from the <strong>Integrations</strong> tab in Stratek: press <strong>Set up</strong> on an integration and enter its keys. Keys stay in this connector (your Cloudflare account); Stratek never sees them.</p>
    <p><a class="btn" href="${esc(back)}">Open Stratek</a></p>
    <p><small>Version ${esc(version)}.</small></p>`);
}

export function messagePage(title, text, kind = 'err', status = 400) {
  return page(title, `<h1>${esc(title)}</h1><p class="${kind}">${esc(text)}</p>`, status);
}

export function connectedPage(pairing, stratekUrl) {
  // Straight back to Stratek's Integrations tab (step 3: Set up integrations).
  const back = pairing.ownerType === 'admin' ? `${stratekUrl}/admin.html#integrations` : `${stratekUrl}/dashboard.html#integrations`;
  return page('Connected', `
    <h1>All set</h1>
    <p class="ok">Connected to <strong>${esc(pairing.ownerName || pairing.ownerType)}</strong>.</p>
    <p>Taking you back to Stratek &rarr; <strong>Integrations</strong>, where you press <strong>Set up</strong> on the integrations you use&hellip;</p>
    <p><a class="btn" href="${esc(back)}">Back to Stratek now</a></p>`, 200, { Refresh: `3; url=${back}` });
}

/**
 * The "Set up" page for one integration. Opened from Stratek's Integrations
 * tab as <connector>/setup/<id>#pass=<one-hour pass>. The pass travels in the
 * URL fragment (never sent to any server) and is removed from the address bar
 * at once. Keys are sent only to this connector (same origin) -- Stratek's
 * page and servers never see them.
 */
export function setupPage(integration, origin = '') {
  const csp = "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; form-action 'none'; base-uri 'none'";
  const t = { support: 'sandbox', note: null, ...(integration.test || {}) };
  const testIntro = t.support === 'none'
    ? `<p class="hint">${esc(t.note || `${integration.name} has no test environment, so it runs with live keys only.`)}</p>`
    : `<p class="hint">Used only where Stratek says "test" (e.g. the online store's test mode, or the "(test keys)" buttons on Stratek's Integrations tab). The till, kiosk and live store always use the live keys.${t.note ? ` ${esc(t.note)}` : ''}</p>`;
  const w = integration.webhookSetup;
  const hookLine = (mode) => w && origin ? `<p class="hint"><strong>${esc(w.what || 'Notifications')}</strong> Callback URL for ${esc(w.where || integration.name)}: <code>${esc(`${origin}/webhooks/${integration.id}${mode === 'test' ? '/test' : ''}`)}</code></p>` : '';
  return page(`Set up ${integration.name}`, `
    <h1>Set up ${esc(integration.name)}</h1>
    <p>${esc(integration.description || '')}</p>
    <div id="msg"></div>
    <section class="mode" data-mode="live"><h2>Live keys</h2><p class="hint">Real customers and real money.</p>${hookLine('live')}
      <form id="f_live" hidden autocomplete="off"><div class="fields"></div><p><button class="btn" type="submit">Save live keys</button></p></form></section>
    <section class="mode" data-mode="test"><h2>Test keys ${t.support === 'none' ? '<small>(not available)</small>' : '<small>(optional)</small>'}</h2>${testIntro}
      ${t.support === 'none' ? '' : hookLine('test')}${t.support === 'none' ? '' : '<form id="f_test" hidden autocomplete="off"><div class="fields"></div><p><button class="btn btn-alt" type="submit">Save test keys</button></p></form>'}</section>
    <p><small>Keys are stored in this connector, in the shop's own Cloudflare account. Stratek never sees them; saved keys are only shown masked.</small></p>
    <style>.mode{border-top:1px solid #e6caca;margin-top:18px;padding-top:6px}h2{font-size:1.1rem;margin:10px 0 2px}.btn-alt{background:#574646}</style>
    <script>
    (function () {
      var id = ${JSON.stringify(integration.id)};
      var m = location.hash.match(/pass=([A-Za-z0-9._-]+)/);
      var pass = m ? m[1] : '';
      history.replaceState(null, '', location.pathname);
      var msg = document.getElementById('msg');
      function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
      function say(text, kind) { msg.innerHTML = text ? '<p class="' + (kind || 'err') + '">' + esc(text) + '</p>' : ''; msg.scrollIntoView({ block: 'nearest' }); }
      if (!pass) { say('Open this page from Stratek: Integrations -> Set up.'); return; }
      function api(method, mode, body) {
        return fetch('/secrets/' + id + (method === 'GET' ? '?mode=' + mode : ''), { method: method, headers: { Authorization: 'Bearer ' + pass, 'Content-Type': 'application/json' }, body: body ? JSON.stringify(body) : undefined })
          .then(function (r) { return r.json().then(function (j) { if (!r.ok || !j.success) throw new Error((j.error && j.error.message) || ('Error ' + r.status)); return j.data; }); });
      }
      function setup(mode) {
        var form = document.getElementById('f_' + mode); if (!form) return;
        var box = form.querySelector('.fields');
        function render(d) {
          box.innerHTML = d.secrets.map(function (s) {
            var fid = 'k_' + mode + '_' + s.name;
            var saved = s.set ? '<div class="saved">Saved: ' + esc(s.masked) + (s.source === 'cloudflare' ? ' (set in Cloudflare)' : '') + ' -- leave empty to keep</div>' : '';
            var rm = s.set && s.source === 'connector' ? '<label class="rm"><input type="checkbox" data-remove="' + esc(s.name) + '"> remove</label>' : '';
            return '<label for="' + esc(fid) + '">' + esc(s.label) + (s.optional ? ' <small>(optional)</small>' : '') + rm + '</label>' +
              '<input type="password" id="' + esc(fid) + '" data-name="' + esc(s.name) + '" spellcheck="false" autocomplete="new-password">' +
              (s.hint ? '<div class="hint">' + esc(s.hint) + '</div>' : '') + saved;
          }).join('');
          form.hidden = false;
        }
        api('GET', mode).then(render).catch(function (e) { say(e.message); });
        form.addEventListener('submit', function (ev) {
          ev.preventDefault();
          var values = {}, remove = [];
          box.querySelectorAll('input[data-name]').forEach(function (i) { if (i.value.trim()) values[i.dataset.name] = i.value.trim(); });
          box.querySelectorAll('input[data-remove]:checked').forEach(function (i) { remove.push(i.dataset.remove); });
          var btn = form.querySelector('button'); btn.disabled = true;
          var label = mode === 'test' ? 'Test keys' : 'Live keys';
          api('POST', mode, { mode: mode, values: values, remove: remove }).then(function (d) {
            render(d);
            if (!d.ready) say(label + ' saved. Still missing: ' + d.missing.join(', ') + '.', 'err');
            else if (d.warning) say(label + ' saved, but: ' + d.warning, 'err');
            else say(label + ' saved. ' + d.name + ' is ready' + (mode === 'test' ? ' in test mode' : '') + (d.notice ? ' -- ' + d.notice : '') + '. Go back to Stratek, it updates by itself.', 'ok');
          }).catch(function (e) { say(e.message); }).then(function () { btn.disabled = false; });
        });
      }
      setup('live'); setup('test');
    })();
    </script>`, 200, { 'Content-Security-Policy': csp });
}

modules.registry.js:
// registry.js -- the list of integrations this connector knows.
//
// Adding an integration = add a file in src/integrations/ and list it in
// src/integrations/catalogue.js. Each one has a `status`:
//   'available' -- built: once its keys are set it is "ready" and its buttons
//                  appear in Stratek;
//   'planned'   -- scaffold only: listed in Stratek as "Coming soon", no
//                  buttons, keys can't be entered yet.
//
// Keys come from the "Set up" form (stored in this connector's Durable Object)
// or from Cloudflare Secrets with the same name; the Set up form wins.

import core from './integrations/core.js';
import { CATALOGUE } from './integrations/catalogue.js';

export const INTEGRATIONS = [core, ...CATALOGUE];

export const CATEGORIES = {
  system: 'Connector',
  payments: 'Payments',
  delivery: 'Delivery, shipping & rides',
  fulfilment: 'Manufacturing & fulfilment',
  sourcing: 'Suppliers & sourcing',
  hospitality: 'Hotels & hospitality',
  messaging: 'Messages & notifications',
  accounting: 'Accounting & tax',
  commerce: 'Online stores & marketplaces',
  marketing: 'Customers & marketing',
  automation: 'Automation',
  ai: 'AI employee',
};

const has = (v) => typeof v === 'string' && v.trim() !== '';
export const statusOf = (i) => i.status || 'available';
export const MODES = ['live', 'test'];
export const modeOf = (m) => (m === 'test' ? 'test' : 'live');

// Test vs live keys. Every integration has two sets of keys, entered
// separately in its Set up page. `test` in an integration describes its test
// environment:
//   support: 'sandbox'    -- provider has a real test environment
//            'real-money' -- test keys exist but some payments still move real money (e.g. Fonepay)
//            'none'       -- provider has no test environment: live only
//   note:    shown on the Set up page
//   omit:    live key names not used in test; extraSecrets: keys only for test
//   hints:   { KEY_NAME: 'test-specific hint' }
export const testInfo = (i) => ({ support: 'sandbox', note: null, ...(i.test || {}) });
export function secretsFor(i, mode = 'live') {
  const all = i.secrets || [];
  if (modeOf(mode) === 'live') return all;
  const t = testInfo(i);
  if (t.support === 'none') return [];
  const omit = new Set(t.omit || []);
  return [
    ...all.filter((s) => !omit.has(s.name)).map((s) => (t.hints?.[s.name] ? { ...s, hint: t.hints[s.name] } : s)),
    ...(t.extraSecrets || []),
  ];
}
export const requiredSecrets = (i, mode = 'live') => secretsFor(i, mode).filter((s) => !s.optional);
export const allSecretNames = () => [...new Set(INTEGRATIONS.flatMap((i) => [...secretsFor(i, 'live'), ...secretsFor(i, 'test')].map((s) => s.name)))];

export function findIntegration(id) {
  return INTEGRATIONS.find((i) => i.id === id) || null;
}

export function isReady(integration, keys, mode = 'live') {
  if (statusOf(integration) !== 'available') return false;
  if (modeOf(mode) === 'test' && testInfo(integration).support === 'none') return false;
  const req = requiredSecrets(integration, mode);
  if (!req.length && modeOf(mode) === 'test' && !(integration.secrets || []).length) return true; // nothing to set (e.g. core)
  return req.every((s) => has(keys[s.name]));
}

/** What the POS gets from GET /manifest -- never includes secret values. `keys` = live, `testKeys` = test. */
export function manifest(keys, testKeys = {}) {
  return INTEGRATIONS.map((i) => {
    const status = statusOf(i);
    const ready = isReady(i, keys);
    const t = testInfo(i);
    const testReady = isReady(i, testKeys, 'test');
    return {
      id: i.id,
      name: i.name,
      category: i.category || 'system',
      description: i.description,
      status,
      docsUrl: i.docsUrl || null,
      color: i.color || null,           // button colour in Stratek
      qrProvider: !!i.qrProvider,       // can make the till/kiosk payment QR (see POS "Use for the till QR")
      ready,                            // live keys complete
      testReady,                        // test keys complete
      test: { support: t.support, note: t.note || null },
      setup: status === 'available' && (i.secrets || []).length > 0,
      missingSecrets: ready ? [] : requiredSecrets(i).filter((s) => !has(keys[s.name])).map((s) => s.name),
      secrets: (i.secrets || []).map((s) => ({ name: s.name, label: s.label, optional: !!s.optional, set: has(keys[s.name]) })),
      testSecrets: secretsFor(i, 'test').map((s) => ({ name: s.name, label: s.label, optional: !!s.optional, set: has(testKeys[s.name]) })),
      actions: (i.actions || []).map(({ run, ...a }) => ({ ...a, outbound: isOutbound(a) })),
    };
  });
}
/**
 * Outbound actions move money out of the shop or commit it to a real-world
 * cost (refunds, booking a rider, paying for a print). A person must run them:
 * API keys / AI agents are refused and use Stratek's approval requests instead.
 * Marked with `outbound: true`; ids like refund / create_delivery / confirm /
 * payout / transfer are treated as outbound even if a scaffold forgets it.
 */
export const isOutbound = (a) => a.outbound === true || (a.outbound !== false && /^(refund|create_delivery|confirm|payout|transfer|send_money)/.test(a.id || ''));

export function findAction(integrationId, actionId) {
  const integration = findIntegration(integrationId);
  const action = integration?.actions?.find((a) => a.id === actionId);
  return integration && action ? { integration, action } : null;
}

modules.state.js:
// state.js -- the connector's tiny memory: which Stratek account it is paired
// with, Stratek's public key, and a one-time "state" value during pairing.
// One Durable Object instance (named "config") per connector.
//
// Plain fetch-based Durable Object (no `cloudflare:workers` import), so the
// rest of the code can be tested in plain Node with a stand-in.

export class ConnectorState {
  constructor(state) {
    this.storage = state.storage;
  }

  async fetch(request) {
    const { op, key, value } = await request.json();
    if (op === 'get') return Response.json({ value: (await this.storage.get(key)) ?? null });
    if (op === 'put') { await this.storage.put(key, value); return Response.json({ ok: true }); }
    if (op === 'delete') { await this.storage.delete(key); return Response.json({ ok: true }); }
    return new Response('bad op', { status: 400 });
  }
}

/** Small helper around the Durable Object. */
export function store(env) {
  const stub = env.STATE.get(env.STATE.idFromName('config'));
  const call = async (op, key, value) => {
    const res = await stub.fetch('https://state/', { method: 'POST', body: JSON.stringify({ op, key, value }) });
    return (await res.json()).value;
  };
  return {
    get: (key) => call('get', key),
    put: (key, value) => call('put', key, value),
    delete: (key) => call('delete', key),
  };
}

modules.storefront.js:
// storefront.js -- the shop's online store served from the shop's OWN
// Cloudflare (v0.11.0): on its own domain (e.g. https://shop.chyaubio.com/) or
// on this connector's workers.dev address (https://<connector>/shop).
//
// The page, menu, orders and payments still come from Stratek (one source of
// truth, same rules): this Worker serves Stratek's store page with a small
// config, and forwards the store's API calls to Stratek, signed with this
// connector's event key so Stratek can trust the customer IP (rate limits) and
// the address the customer used (order links). Only GET/POST of the store API
// for this shop's own store are forwarded -- nothing else of Stratek.
//
// Config (set by Stratek with a pass, POST /storefront):
//   { slug, workersDev: boolean, hostnames: ['shop.example.com'] }

const b64url = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const HOST_RE = /^(?=.{4,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const STATIC = /^\/(js|assets)\/[\w./-]{1,120}$|^\/media\/menu\/[\w./-]{1,200}$/;
const MAX_BODY = 64 * 1024;

export function cleanStorefront(body) {
  const slug = String(body?.slug || '').toLowerCase();
  if (!/^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$/.test(slug)) throw Object.assign(new Error('Bad store link.'), { status: 400 });
  const hostnames = (Array.isArray(body?.hostnames) ? body.hostnames : []).map((h) => String(h).toLowerCase().trim()).filter(Boolean);
  if (hostnames.length > 3 || hostnames.some((h) => !HOST_RE.test(h) || h.endsWith('.workers.dev'))) throw Object.assign(new Error('Bad domain name.'), { status: 400 });
  return { slug, workersDev: !!body?.workersDev, hostnames, updatedAt: new Date().toISOString() };
}

/** Which storefront (if any) this request is for -> { cfg, base } or null. */
export function matchStorefront(cfg, url) {
  if (!cfg?.slug) return null;
  if (cfg.hostnames?.includes(url.hostname)) return { cfg, base: '' };
  if (cfg.workersDev && url.hostname.endsWith('.workers.dev') && (url.pathname === '/shop' || url.pathname.startsWith('/shop/'))) return { cfg, base: '/shop' };
  if (cfg.workersDev && url.hostname.endsWith('.workers.dev') && STATIC.test(url.pathname)) return { cfg, base: '/shop', staticOnly: true };
  return null;
}

async function sign(db, keyPairFn, parts) {
  const kp = await keyPairFn(db);
  const key = await crypto.subtle.importKey('jwk', { ...kp.priv, key_ops: ['sign'] }, { name: 'Ed25519' }, false, ['sign']);
  const t = Math.floor(Date.now() / 1000);
  const sig = b64url(await crypto.subtle.sign({ name: 'Ed25519' }, key, new TextEncoder().encode(`${t}.${parts.join('.')}`)));
  return `t=${t},sig=${sig}`;
}

const notFound = () => new Response('Not found', { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });

/** Serves one storefront request. */
export async function serveStorefront(request, { db, pairing, stratekUrl, match, keyPair }) {
  const url = new URL(request.url);
  const { cfg, base } = match;
  const path = url.pathname.slice(base.length) || '/';
  const origin = `${url.origin}${base}`;

  // Static files of the store page (Stratek's own), GET only.
  if (STATIC.test(url.pathname)) {
    if (request.method !== 'GET' && request.method !== 'HEAD') return notFound();
    const res = await fetch(`${stratekUrl}${url.pathname}`, { cf: { cacheTtl: 300 } });
    return new Response(res.body, { status: res.status, headers: res.headers });
  }
  if (match.staticOnly) return notFound();
  if (!pairing) return new Response('This store is not connected yet.', { status: 503 });

  // The store's API -> Stratek, signed.
  const api = path.match(/^\/api(\/[\w./-]*)?$/);
  if (api) {
    if (!['GET', 'POST'].includes(request.method)) return notFound();
    const rest = api[1] || '';
    if (rest.includes('..')) return notFound();
    const body = request.method === 'POST' ? await request.text() : null;
    if (body && body.length > MAX_BODY) return new Response('Too large.', { status: 413 });
    const target = `/api/v1/store/${cfg.slug}${rest}${url.search}`;
    const ip = request.headers.get('CF-Connecting-IP') || '';
    const sig = await sign(db, keyPair, [request.method, target, ip, origin]);
    const res = await fetch(`${stratekUrl}${target}`, {
      method: request.method,
      headers: {
        'Content-Type': 'application/json',
        'X-Stratek-Connector': pairing.connectorId,
        'X-Stratek-Storefront': sig,
        'X-Store-Client-IP': ip,
        'X-Store-Origin': origin,
      },
      body,
    });
    return new Response(res.body, { status: res.status, headers: { 'Content-Type': res.headers.get('Content-Type') || 'application/json', 'Cache-Control': 'no-store' } });
  }

  // The page itself: / and /order/<token>.
  if (request.method === 'GET' && (/^\/?$/.test(path) || /^\/order\/[A-Za-z0-9_-]{20,200}\/?$/.test(path))) {
    const res = await fetch(`${stratekUrl}/store/${cfg.slug}`, { cf: { cacheTtl: 60 } });
    if (!res.ok) return new Response('The store page is not available right now.', { status: 502 });
    const html = (await res.text()).replace('</head>', `<script>window.STRATEK_STORE=${JSON.stringify({ slug: cfg.slug, base })};</script></head>`);
    return new Response(html, {
      status: 200,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-store',
        'X-Frame-Options': 'DENY',
        'Referrer-Policy': 'strict-origin-when-cross-origin',
      },
    });
  }
  if (base === '/shop' && url.pathname === '/shop') return Response.redirect(`${url.origin}/shop/`, 301);
  return notFound();
}

modules.version.js:
// Bumped with every release; the Stratek Integrations tab compares it with
// the latest version on GitHub and shows "update available".
export const CONNECTOR_VERSION = '0.19.0';
export const UPSTREAM_REPO = 'https://github.com/carbonupdates/stratek-connectors';
